     1|/**
     2| * Owner-facing "Generate Worker Access" endpoint.
     3| *
     4| * Lets the registered IVX owner mint a short-lived (5-15 minute), single-use,
     5| * action- and commit-SHA-bound worker access token using their existing live
     6| * Supabase session — no raw JWT ever needs to be copied into Render.
     7| *
     8| * The response returns the raw token exactly once. Only its SHA-256 hash is
     9| * ever persisted (see ivx-worker-access-token.ts). The worker later presents
    10| * this token, alongside its existing signed HMAC identity, to consume it via
    11| * the extended /internal-deployment-authorizations/consume flow.
    12| */
    13|import { assertIVXRegisteredOwnerBearer, ownerOnlyJson, ownerOnlyOptions } from './owner-only';
    14|import {
    15|  generateWorkerAccessToken,
    16|  isAllowedWorkerAccessAction,
    17|  normalizeTtlMinutes,
    18|  WorkerAccessTokenError,
    19|  type WorkerAccessAction,
    20|} from '../services/ivx-worker-access-token';
    21|import { writeProofLedger } from '../services/ivx-senior-dev-proof';
    22|
    23|function text(value: unknown): string {
    24|  return typeof value === 'string' ? value.trim() : '';
    25|}
    26|
    27|export function OPTIONS(): Response {
    28|  return ownerOnlyOptions();
