    31|export async function handleGenerateWorkerAccessRequest(request: Request): Promise<Response> {
    32|  const requestId = `worker-access-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    33|  try {
    34|    const { context, approval } = await assertIVXRegisteredOwnerBearer(request, 'generate_worker_access');
    35|    const body = await request.json().catch((): Record<string, unknown> => ({}));
    36|
    37|    const action = text(body.action) as WorkerAccessAction;
    38|    const commitSha = text(body.commitSha).toLowerCase();
    39|    const workerId = text(body.workerId) || null;
    40|    const ttlMinutes = normalizeTtlMinutes(body.ttlMinutes);
    41|
    42|    if (!isAllowedWorkerAccessAction(action)) {
    43|      return ownerOnlyJson({
    44|        ok: false,
    45|        error: 'A valid action (GITHUB_WRITE, RENDER_DEPLOY, PRODUCTION_DEPLOY, or QA_ONLY) is required.',
    46|        secretValuesReturned: false,
    47|      }, 400);
    48|    }
    49|    if (!/^[a-f0-9]{40}$/i.test(commitSha)) {
    50|      return ownerOnlyJson({
    51|        ok: false,
    52|        error: 'A 40-character commitSha is required.',
    53|        secretValuesReturned: false,
    54|      }, 400);
    55|    }
    56|
    57|    const { rawToken, record } = await generateWorkerAccessToken({
    58|      ownerId: context.userId,
    59|      action,
    60|      commitSha,
    61|      requestId,
    62|      workerId,
    63|      ttlMinutes,
    64|    });
    65|
    66|    // Best-effort proof-ledger issuance record. Never include the raw token.
    67|    await writeProofLedger({
    68|      taskId: record.id,
    69|      workerId: workerId ?? 'unassigned',
    70|      commitSha,
    71|      status: 'running',
    72|      logs: [
    73|        `worker_access_token_issued action=${action} owner=${context.userId} ttlMinutes=${ttlMinutes} tokenId=${record.id}`,
    74|      ],
    75|    }).catch(() => null);
    76|
    77|    return ownerOnlyJson({
    78|      ok: true,
    79|      ownerOnly: true,
    80|      ownerApproval: approval,
    81|      workerAccessToken: rawToken,
    82|      authorization: {
    83|        id: record.id,
    84|        action: record.action,
    85|        commitSha: record.commitSha,
    86|        workerId: record.workerId,
    87|        issuedAt: record.issuedAt,
    88|        expiresAt: record.expiresAt,
    89|      },
    90|      tokenStoredAsHashOnly: true,
    91|      secretValuesReturned: false,
    92|      timestamp: new Date().toISOString(),
    93|    }, 201);
    94|  } catch (error) {
    95|    if (error instanceof WorkerAccessTokenError) {
    96|      return ownerOnlyJson({ ok: false, error: error.message.slice(0, 300), code: error.code, secretValuesReturned: false }, error.status);
    97|    }
    98|    const message = error instanceof Error ? error.message : 'Worker access token could not be generated.';
    99|    const status = message.toLowerCase().includes('bearer') || message.toLowerCase().includes('invalid or expired') ? 401 : 403;
   100|    return ownerOnlyJson({ ok: false, error: message.slice(0, 300), secretValuesReturned: false }, status);
   101|  }
