    84|export type GenerateWorkerAccessInput = {
    85|  ownerId: string;
    86|  action: WorkerAccessAction;
    87|  commitSha: string;
    88|  requestId: string;
    89|  workerId?: string | null;
    90|  ttlMinutes?: number;
    91|};
