    98|/**
    99| * Mints a new short-lived worker access token. Returns the raw token exactly
   100| * once — callers MUST NOT log it. Only the hash is persisted.
   101| */
   102|export async function generateWorkerAccessToken(
   103|  input: GenerateWorkerAccessInput,
   104|  store: WorkerAccessTokenStore = durableTokenStore,
   105|): Promise<GenerateWorkerAccessResult> {
   106|  const commitSha = input.commitSha.trim().toLowerCase();
   107|  if (!isValidCommitSha(commitSha)) {
   108|    throw new WorkerAccessTokenError('A 40-character commitSha is required.', 400, 'INVALID_COMMIT_SHA');
   109|  }
   110|  if (!isAllowedWorkerAccessAction(input.action)) {
   111|    throw new WorkerAccessTokenError('The requested action is not an allowed worker action.', 400, 'INVALID_ACTION');
   112|  }
   113|  if (!input.ownerId.trim()) {
   114|    throw new WorkerAccessTokenError('An authenticated owner ID is required.', 401, 'MISSING_OWNER');
   115|  }
   116|
   117|  const ttlMinutes = normalizeTtlMinutes(input.ttlMinutes);
   118|  const rawToken = randomBytes(32).toString('base64url');
   119|  const now = new Date();
   120|  const record: WorkerAccessTokenRecord = {
   121|    id: crypto.randomUUID(),
   122|    ownerId: input.ownerId,
   123|    action: input.action,
   124|    commitSha,
   125|    tokenHash: hashToken(rawToken),
   126|    workerId: input.workerId?.trim() || null,
   127|    requestId: input.requestId,
   128|    issuedAt: now.toISOString(),
   129|    expiresAt: new Date(now.getTime() + ttlMinutes * 60_000).toISOString(),
   130|    usedAt: null,
   131|    revokedAt: null,
   132|    revokedReason: null,
   133|    createdAt: now.toISOString(),
   134|  };
   135|
   136|  const existing = await store.readJson<WorkerAccessTokenRecord[]>(TOKEN_STORE, []);
   137|  existing.push(record);
   138|  await store.writeJson(TOKEN_STORE, existing.slice(-MAX_STORED_TOKENS));
   139|
   140|  const { tokenHash: _tokenHash, ...recordWithoutHash } = record;
   141|  return { rawToken, record: recordWithoutHash };
   142|}
