   144|export type ConsumeWorkerAccessInput = {
   145|  rawToken: string;
   146|  action: WorkerAccessAction;
   147|  commitSha: string;
   148|  workerId: string;
   149|};
   150|
   151|export type ConsumeWorkerAccessResult = {
   152|  id: string;
   153|  ownerId: string;
   154|  action: WorkerAccessAction;
   155|  commitSha: string;
   156|};
   157|
   158|/**
   159| * Atomically validates and consumes one worker access token. Enforces:
   160| * expiry, single-use, revocation, exact action match, exact commit-SHA match,
   161| * and (when the token is worker-bound) exact worker-ID match. Replays of an
   162| * already-used or unknown token are rejected.
   163| */
   164|export async function consumeWorkerAccessToken(
   165|  input: ConsumeWorkerAccessInput,
   166|  store: WorkerAccessTokenStore = durableTokenStore,
   167|): Promise<ConsumeWorkerAccessResult> {
   168|  const presentedHash = hashToken(input.rawToken);
   169|  const commitSha = input.commitSha.trim().toLowerCase();
   170|  const tokens = await store.readJson<WorkerAccessTokenRecord[]>(TOKEN_STORE, []);
   171|  const index = tokens.findIndex((token) => token.tokenHash === presentedHash);
   172|  const record = index >= 0 ? tokens[index] : null;
   173|
   174|  if (!record) {
   175|    throw new WorkerAccessTokenError('Worker access token is invalid or unknown.', 401, 'TOKEN_INVALID');
   176|  }
   177|  if (record.revokedAt) {
   178|    throw new WorkerAccessTokenError('Worker access token has been revoked.', 403, 'TOKEN_REVOKED');
   179|  }
   180|  if (record.usedAt) {
   181|    throw new WorkerAccessTokenError('Worker access token has already been used.', 409, 'TOKEN_REPLAY');
   182|  }
   183|  if (Date.parse(record.expiresAt) <= Date.now()) {
   184|    throw new WorkerAccessTokenError('Worker access token has expired.', 401, 'TOKEN_EXPIRED');
   185|  }
   186|  if (record.action !== input.action) {
   187|    throw new WorkerAccessTokenError('Worker access token does not authorize this action.', 403, 'ACTION_MISMATCH');
   188|  }
   189|  if (record.commitSha !== commitSha) {
   190|    throw new WorkerAccessTokenError('Worker access token does not authorize this commit.', 403, 'COMMIT_MISMATCH');
   191|  }
   192|  if (record.workerId && record.workerId !== input.workerId) {
   193|    throw new WorkerAccessTokenError('Worker access token is bound to a different worker.', 403, 'WORKER_MISMATCH');
   194|  }
   195|
   196|  tokens[index] = { ...record, usedAt: new Date().toISOString() };
   197|  await store.writeJson(TOKEN_STORE, tokens);
   198|
   199|  return { id: record.id, ownerId: record.ownerId, action: record.action, commitSha: record.commitSha };
   200|}
   201|
   202|export async function revokeWorkerAccessToken(
   203|  tokenId: string,
   204|  reason: string,
   205|  store: WorkerAccessTokenStore = durableTokenStore,
   206|): Promise<boolean> {
   207|  const tokens = await store.readJson<WorkerAccessTokenRecord[]>(TOKEN_STORE, []);
   208|  const index = tokens.findIndex((token) => token.id === tokenId);
   209|  if (index < 0) return false;
   210|  const record = tokens[index];
   211|  if (!record || record.usedAt || record.revokedAt) return false;
   212|  tokens[index] = { ...record, revokedAt: new Date().toISOString(), revokedReason: reason.slice(0, 300) };
   213|  await store.writeJson(TOKEN_STORE, tokens);
   214|  return true;
