type AutonomousQAAuthState = 'idle' | 'authorizing' | 'authorized' | 'failed';

type AutonomousQAAuthResult = {
  authorizationId: string;
  action: string;
  commitSha: string;
  workerId: string | null;
  issuedAt: string;
  expiresAt: string;
};

/**
 * Owner-only control that mints a short-lived, single-use worker access token
 * using the owner's CURRENT live Supabase session -- never a pasted/static token.
 *
 * Flow: getSession() -> (one bounded refreshSession() retry if expired) ->
 * POST /api/ivx/senior-developer/generate-worker-access with the fresh
 * session.access_token -> show only the returned authorization metadata
 * (never the raw token, which is not persisted here or logged).
 */
function AuthorizeAutonomousQACard() {
  const router = useRouter();
  const { userRole, isAuthenticated } = useAuth();
  const [state, setState] = useState<AutonomousQAAuthState>('idle');
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [result, setResult] = useState<AutonomousQAAuthResult | null>(null);

  const isOwnerOrAdmin = userRole === 'owner' || userRole === 'admin';
  if (!isAuthenticated || !isOwnerOrAdmin) {
    return null;
  }

  const resolveCurrentCommitSha = async (): Promise<string | null> => {
    try {
      const response = await fetch(`${getDirectApiBaseUrl().replace(/\/+$/, '')}/version`, {
        headers: { Accept: 'application/json' },
      });
      if (!response.ok) return null;
      const payload = (await response.json().catch(() => null)) as Record<string, unknown> | null;
      const sha = typeof payload?.sha === 'string' ? payload.sha
        : typeof payload?.commitSha === 'string' ? payload.commitSha
        : typeof payload?.commit === 'string' ? payload.commit
        : null;
      return sha && /^[a-f0-9]{40}$/i.test(sha) ? sha.toLowerCase() : null;
    } catch {
      return null;
    }
  };

  const handleAuthorize = async (retried = false) => {
    setState('authorizing');
    setErrorMessage(null);
    try {
      let sessionResult = await supabase.auth.getSession();
      let session = sessionResult.data.session;

      if (!session?.access_token || sessionResult.error) {
        const refreshResult = await supabase.auth.refreshSession();
        session = refreshResult.data.session;
      }

      if (!session?.access_token) {
        if (!retried) {
          setState('idle');
          Alert.alert(
            'Sign In Required',
            'Your owner session has expired. Please sign in again, then tap Authorize once more.',
            [{ text: 'Go to Login', onPress: () => router.push('/login' as any) }],
          );
          return;
        }
        throw new Error('No valid owner session is available after sign-in.');
      }

      const commitSha = await resolveCurrentCommitSha();
      if (!commitSha) {
        throw new Error('Could not resolve the current production commit SHA from /version.');
      }

      const response = await fetch(
        `${getDirectApiBaseUrl().replace(/\/+$/, '')}/api/ivx/senior-developer/generate-worker-access`,
        {
          method: 'POST',
          headers: {
            Accept: 'application/json',
            'Content-Type': 'application/json',
            Authorization: `Bearer ${session.access_token}`,
          },
          body: JSON.stringify({
            action: 'QA_ONLY',
            commitSha,
            workerId: 'ivx-senior-dev-01',
            ttlMinutes: 10,
          }),
        },
      );

      const payload = (await response.json().catch(() => null)) as Record<string, unknown> | null;

      if (!response.ok) {
        const message = typeof payload?.error === 'string' ? payload.error : `Authorization failed with HTTP ${response.status}.`;
        throw new Error(message);
      }

      const authorization = (payload?.authorization ?? null) as Record<string, unknown> | null;
      if (!authorization || typeof authorization.id !== 'string') {
        throw new Error('Authorization endpoint returned an unexpected response shape.');
      }

      setResult({
        authorizationId: authorization.id,
        action: typeof authorization.action === 'string' ? authorization.action : 'QA_ONLY',
        commitSha: typeof authorization.commitSha === 'string' ? authorization.commitSha : commitSha,
        workerId: typeof authorization.workerId === 'string' ? authorization.workerId : null,
        issuedAt: typeof authorization.issuedAt === 'string' ? authorization.issuedAt : new Date().toISOString(),
        expiresAt: typeof authorization.expiresAt === 'string' ? authorization.expiresAt : '',
      });
      setState('authorized');
    } catch (e: any) {
      setState('failed');
      setErrorMessage(e?.message ?? 'Authorization failed for an unknown reason.');
    }
  };

  return (
    <View style={qaCardStyles.container}>
      <View style={qaCardStyles.header}>
        <View style={qaCardStyles.iconWrap}>
          <Zap size={20} color="#FFB020" />
        </View>
        <View style={{ flex: 1 }}>
          <Text style={qaCardStyles.title}>Authorize Autonomous QA</Text>
          <Text style={qaCardStyles.sub}>Mints a 10-minute, single-use worker token from your live session</Text>
        </View>
      </View>

      {state === 'authorized' && result ? (
        <View style={qaCardStyles.resultBox}>
          <Text style={qaCardStyles.resultLine}>Authorization ID: {result.authorizationId}</Text>
          <Text style={qaCardStyles.resultLine}>Action: {result.action}</Text>
          <Text style={qaCardStyles.resultLine}>Commit: {result.commitSha.slice(0, 12)}</Text>
          <Text style={qaCardStyles.resultLine}>Expires: {result.expiresAt ? new Date(result.expiresAt).toLocaleTimeString() : '-'}</Text>
        </View>
      ) : null}

      {state === 'failed' && errorMessage ? (
        <Text style={qaCardStyles.errorText}>{errorMessage}</Text>
      ) : null}

      <TouchableOpacity
        style={[qaCardStyles.actionBtn, (state === 'authorizing') && qaCardStyles.actionBtnDisabled]}
        onPress={() => handleAuthorize(false)}
        disabled={state === 'authorizing'}
        testID="authorize-autonomous-qa-button"
      >
        <Shield size={16} color="#000" />
        <Text style={qaCardStyles.actionBtnText}>
          {state === 'authorizing' ? 'Authorizing...' : state === 'authorized' ? 'Re-authorize' : 'Authorize Autonomous QA'}
        </Text>
      </TouchableOpacity>
    </View>
  );
}

